<section class="hero"><p class="eyebrow">OYUN DÜNYASINA HIZLI ERİŞİM</p><h1><?= e($settings['home_heading']??($settings['site_title']??'')) ?></h1><p><?= e($settings['home_description']??'') ?></p></section><?php if($categories): ?><section><h2>Kategoriler</h2><div class="chips"><?php foreach($categories as $c): ?><a class="chip" href="<?= e(url('category/'.rawurlencode($c['slug']))) ?>"><?= e($c['name']) ?></a><?php endforeach; ?></div></section><?php endif; ?><section><h2>Öne çıkan ürünler</h2><?php if(!$products): ?><div class="empty">Henüz yayında ürün bulunmuyor.</div><?php else: ?><div class="products"><?php foreach($products as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?></div><?php endif; ?></section>
